package com.ringbreakalert;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class RingBreakAlertPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(RingBreakAlertPlugin.class);
        RuneLite.main(args);
    }
}

package com.ringbreakalert;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RingBreakAlertMessageTest
{
    @Test
    public void detectsRingCrumbleMessages()
    {
        assertTrue(RingBreakAlertPlugin.isRingCrumbleMessage("Your ring of dueling has crumbled to dust."));
        assertTrue(RingBreakAlertPlugin.isRingCrumbleMessage("Your ring crumbles to dust."));
    }

    @Test
    public void ignoresOtherMessages()
    {
        assertFalse(RingBreakAlertPlugin.isRingCrumbleMessage("Your amulet has crumbled to dust."));
        assertFalse(RingBreakAlertPlugin.isRingCrumbleMessage("You have 1 charge left."));
    }
}

package com.ringbreakalert;

public enum AlertSound
{
    GLASS_BOTTLE("Glass bottle breaking (default)"),
    CUSTOM_WAV("Custom .wav file"),
    RUNESCAPE_SOUND("RuneScape sound ID");

    private final String name;

    AlertSound(String name)
    {
        this.name = name;
    }

    @Override
    public String toString()
    {
        return name;
    }
}

package com.ringbreakalert;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.google.inject.Provides;
import java.io.File;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.Notifier;
import net.runelite.client.RuneLite;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
        name = "Ring Break Alert",
        description = "Plays a customizable sound when a degradable ring crumbles to dust",
        tags = {"ring", "break", "crumbles", "sound", "alert"}
)
public class RingBreakAlertPlugin extends Plugin
{
    private static final Logger log =
            LoggerFactory.getLogger(RingBreakAlertPlugin.class);
    private static final String DEFAULT_SOUND_RESOURCE = "/sounds/glass_bottle_break.wav";
    private static final File PLUGIN_DIR = new File(RuneLite.RUNELITE_DIR, "ringbreakalert");

    @Inject
    private Client client;

    @Inject
    private RingBreakAlertConfig config;

    @Inject
    private Notifier notifier;

    @Inject
    private AudioPlayer audioPlayer;

    @Provides
    RingBreakAlertConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(RingBreakAlertConfig.class);
    }

    @Override
    protected void startUp()
    {
        if (!PLUGIN_DIR.exists() && !PLUGIN_DIR.mkdirs())
        {
            log.warn("Unable to create Ring Break Alert plugin directory: {}", PLUGIN_DIR);
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE)
        {
            return;
        }

        String message = event.getMessage();
        if (message == null)
        {
            return;
        }

        String normalized = message
                .replaceAll("<[^>]*>", "")
                .toLowerCase();

        if (!isRingCrumbleMessage(normalized))
        {
            return;
        }

        playConfiguredSound();

        if (config.desktopNotification())
        {
            notifier.notify("Your ring crumbled to dust.");
        }
    }

    private void playConfiguredSound()
    {
        AlertSound selected = config.alertSound();

        if (selected == AlertSound.RUNESCAPE_SOUND)
        {
            int gameVolume = Math.round(config.volume() * 1.27f);
            client.playSoundEffect(config.soundId(), gameVolume);
            return;
        }

        try
        {
            if (selected == AlertSound.CUSTOM_WAV)
            {
                playCustomWav();
            }
            else
            {
                playBundledGlassSound();
            }
        }
        catch (Exception ex)
        {
            log.warn("Unable to play Ring Break Alert sound", ex);
        }
    }

    private void playBundledGlassSound() throws Exception
    {
        audioPlayer.play(
                RingBreakAlertPlugin.class,
                DEFAULT_SOUND_RESOURCE,
                getAudioGain()
        );
    }

    private void playCustomWav() throws Exception
    {
        String fileName = config.customSoundPath();

        if (fileName == null || fileName.trim().isEmpty())
        {
            notifier.notify("Ring Break Alert: enter a WAV filename from .runelite/ringbreakalert/.");
            return;
        }

        File pluginDir = PLUGIN_DIR.getCanonicalFile();
        File file = new File(pluginDir, fileName.trim()).getCanonicalFile();

        String pluginDirPath = pluginDir.getPath() + File.separator;
        if (!file.getPath().startsWith(pluginDirPath))
        {
            notifier.notify("Ring Break Alert: custom sounds must stay inside .runelite/ringbreakalert/.");
            return;
        }

        if (!file.getName().toLowerCase().endsWith(".wav"))
        {
            notifier.notify("Ring Break Alert: custom sound must be a .wav file.");
            return;
        }

        if (!file.isFile())
        {
            notifier.notify("Ring Break Alert: WAV file not found in .runelite/ringbreakalert/.");
            return;
        }

        audioPlayer.play(file, getAudioGain());
    }

    private float getAudioGain()
    {
        int volume = Math.max(0, Math.min(100, config.volume()));

        if (volume == 0)
        {
            return -80.0f;
        }

        float linear = volume / 100.0f;

        return (float) (20.0 * Math.log10(linear));
    }

    static boolean isRingCrumbleMessage(String message)
    {
        if (message == null)
        {
            return false;
        }

        String text = message.toLowerCase();

        return text.contains("ring")
                && (text.contains("crumbled to dust")
                || text.contains("crumbles to dust"));
    }
}

package com.ringbreakalert;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(RingBreakAlertConfig.GROUP)
public interface RingBreakAlertConfig extends Config
{
    String GROUP = "ringbreakalert";

    @ConfigItem(
        keyName = "alertSound",
        name = "Alert sound",
        description = "Choose the sound played when a ring crumbles",
        position = 0
    )
    default AlertSound alertSound()
    {
        return AlertSound.GLASS_BOTTLE;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(
        keyName = "volume",
        name = "Volume",
        description = "Alert volume from 0 to 100",
        position = 1
    )
    default int volume()
    {
        return 100;
    }

    @ConfigItem(
        keyName = "customSoundPath",
        name = "Custom WAV filename",
        description = "Filename of a .wav stored inside .runelite/ringbreakalert/, for example ring.wav",
        position = 2
    )
    default String customSoundPath()
    {
        return "";
    }

    @ConfigItem(
        keyName = "soundId",
        name = "RuneScape sound ID",
        description = "Used only when Alert sound is set to RuneScape sound ID",
        position = 3
    )
    default int soundId()
    {
        return 2266;
    }



    @ConfigItem(
        keyName = "desktopNotification",
        name = "Desktop notification",
        description = "Also show a RuneLite notification when the ring crumbles",
        position = 5
    )
    default boolean desktopNotification()
    {
        return false;
    }
}
